window.AUTH=window.AUTH||{};window.AUTH["19-546"]={"d":"19-546","id":"2020/19-546","n":"Brownback v. King","briefs":[{"k":"petitioner","label":"Brief of petitioners Douglas Brownback, et al.","date":"2020-06-19","url":"https://www.supremecourt.gov/DocketPDF/19/19-546/145995/20200619172637885_19-546tsUnitedStates.pdf","side":"pet","n":61},{"k":"respondent","label":"Brief of respondent James King","date":"2020-08-24","url":"https://www.supremecourt.gov/DocketPDF/19/19-546/151080/20200824154850820_39781%20pdf%20Gammon%20br.pdf","side":"res","n":94},{"k":"reply","label":"Reply of petitioners Douglas Brownback, et al.","date":"2020-09-23","url":"https://www.supremecourt.gov/DocketPDF/19/19-546/154751/20200923165930861_19-546rbUnitedStates.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-546_7mip.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"44","2":"13"}},{"t":"case","label":"Ashbourne v. Hansberry","cite":"894 F.3d 298","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/894/298/","by":{"0":"37"}},{"t":"case","label":"Atherton v. Jewell","cite":"689 Fed. Appx. 643","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./689/643/","by":{"0":"36"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"op":6,"ar":26,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"7, 13, 17, 19","2":"1"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"op":1,"sum":"The Court determined that the “frivolous or insubstantial” standard is not consistent with the text and purpose of the Foreign Sovereign Immunities Act (FSIA)","sumSrc":"Oyez","by":{"0":"34","1":"39, 40, 43","2":"6, 9"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"ar":1,"sum":"Respondent brought suit in Federal District Court in Indiana on behalf of her deceased son's estate, alleging that her son while a prisoner in a federal prison in Indiana suffered personal injuries from which he died because petitioner prison officials violated, inter alia, his Eighth Amendment rights by failing to give him proper medical attention. Asserting jurisdiction under 28 U. S. C. § 1331 (a), respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 25","1":"passim","2":"19"}},{"t":"case","label":"Dalehite v. United States","cite":"346 U.S. 15","y":1953,"id":"scdb/1952-101","sc":1,"sum":"As a matter of law, the facts found by the District Court cannot give it jurisdiction of the cause under the Act, because the claim is \"based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the plirt of a federal agency or an employee of the Government,\" within the meaning of 28 U. S. C. § 2680 (a), which makes the Act inapplicable to such claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 3","1":"14"}},{"t":"case","label":"Dozier v. Ford Motor Co.","cite":"702 F.2d 1189","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/702/1189/","sum":"Describing the jurisdictional-dismissal exception to claim preclusion as covering “curable defect[s],” when a precondition absent from the first lawsuit can be and is remedied before the second lawsuit.","sumSrc":"brief:0","by":{"0":"35"}},{"t":"case","label":"Estate of Trentadue ex rel. Aguilar v. United States","cite":"397 F.3d 840","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/397/840/","by":{"0":"19, 43","1":"34"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"op":3,"ar":2,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 11, 15, 29, 32","1":"passim","2":"2, 4, 5"}},{"t":"case","label":"Farmer v. Perrill","cite":"275 F.3d 958","y":2001,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/275/958/","by":{"0":"36"}},{"t":"case","label":"Fazaga v. FBI","cite":"916 F.3d 1202","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/916/1202/","by":{"0":"43"}},{"t":"case","label":"Gasho v. United States","cite":"39 F.3d 1420","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/39/1420/","by":{"0":"19","1":"30","2":"10"}},{"t":"case","label":"Grubb v. Public Utils. Comm’n","cite":"281 U.S. 470","y":1930,"id":"scdb/1929-064","sc":1,"sum":"conclusive as res judicata in a suit in the federal court, upon the questions whether the prohibition in the order violated rights of the appellant under the commerce clause of the Federal Constitution and under the privileges and immunities clause of the Fourteenth Amendment. P. 475. GRUBB v. PUBLIC UTILITIES COMM. Counsel for Parties.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","1":"17"}},{"t":"case","label":"Harris v. United States","cite":"422 F.3d 322","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/422/322/","by":{"0":"19, 37, 43, 45","1":"34"}},{"t":"case","label":"Hart Steel Co. v. Railroad Supply Co.","cite":"244 U.S. 294","y":1917,"id":"scdb/1916-083","sc":1,"sum":"A patent owner sued for infringement in two circuits, the defendants being, in one case, a corporation which manufactured the articles complained of, and, in the other, a second corporation whose shares were owned, and whose conduct' was controlled, by the first and which, with its manager (joined with it as co-defendant), was acting as the selling agent of the first corporation under its authority and in its …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Haywood v. Drown","cite":"556 U.S. 729","y":2009,"id":"2008/07-10374","sc":1,"sum":"The Court found that prohibiting civil claims against correction officers in their official capacities violated the Supremacy Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Himmelreich v. Federal Bureau of Prisons","cite":"766 F.3d 576","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/766/576/","by":{"0":"11, 12, 30, 31","1":"6"}},{"t":"case","label":"Hui v. Castaneda","cite":"559 U.S. 799","y":2010,"id":"2009/08-1529","sc":1,"sum":"The Court held that the immunity granted by the Federal Tort Claims Act precludes Bivens actions against Public Health Service officers for constitutional violations committed while in the scope of the employees' official duties.","sumSrc":"Oyez","by":{"0":"14, 20, 26, 39, 44","2":"20"}},{"t":"case","label":"Kimble v. Marvel Entm’t, LLC","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Kosak v. United States","cite":"465 U.S. 848","y":1984,"id":"1983/82-618","sc":1,"sum":"Section 2680(c) precludes recovery against the United States for the alleged injury to petitioner's property.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Levin v. United States","cite":"568 U.S. 503","y":2013,"id":"2012/11-1351","sc":1,"sum":"The Court held that the Gonzalez Act made an exception to the Federal Tort Claims Act by saying that a claim of the intentional tort of battery may be brought against an armed forces physician.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Lucky Brand Dungarees, Inc. v. Marcel Fashions Grp., Inc.","cite":"140 S. Ct. 1589","y":2020,"id":"2019/18-1086","sc":1,"op":1,"sum":"The Court held that because the trademark action at issue challenged different conduct—and raised different claims—from an earlier action between the parties, Marcel cannot preclude Lucky Brand from raising new defenses, including a defense that Lucky Brand failed to press fully in the earlier suit.","sumSrc":"Oyez","by":{"0":"22, 42","1":"26"}},{"t":"case","label":"Manning v. United States","cite":"546 F.3d 430","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/546/430/","ar":2,"sum":"Noting that its interpretation of the judgment bar—which the government presses here—had been characterized as “nonsensical” and “harsh, if not Kafka-esque”.","sumSrc":"brief:1","by":{"0":"19, 20, 36, 43, 44","1":"passim"}},{"t":"case","label":"Millbrook v. United States","cite":"569 U.S. 50","y":2013,"id":"2012/11-10362","sc":1,"ar":1,"sum":"The Court held that claims against the United States for the intentional torts of prison officials is not limited to violations made during searches, seizures, or arrests.","sumSrc":"Oyez","by":{"0":"4, 44","2":"16"}},{"t":"case","label":"Odom v. Wayne Cnty.","cite":"760 N.W.2d 217","y":2008,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/760/217/","op":2,"by":{"0":"10"}},{"t":"case","label":"Pesnell v. Arsenault","cite":"543 F.3d 1038","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/543/1038/","by":{"0":"36"}},{"t":"case","label":"Richards v. United States","cite":"369 U.S. 1","y":1962,"id":"1961/59","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"13"}},{"t":"case","label":"Robers v. United States","cite":"572 U.S. 639","y":2014,"id":"2013/12-9012","sc":1,"sum":"The Court held that, under the Mandatory Victims Restitution Act, individuals accused of property crime must pay “an amount equal to...the value of the property,” minus “the value...of any part of the property that is returned\" in retribution.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Rodriguez v. Handy","cite":"873 F.2d 814","y":1989,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/873/814/","sum":"Holding that the judgment bar precluded common-law claims against federal employees individually that were brought in the same lawsuit as FTCA claims.","sumSrc":"brief:0","by":{"0":"43","1":"34"}},{"t":"case","label":"Rose v. Town of Harwich","cite":"778 F.2d 77","y":1985,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/778/77/","by":{"0":"35","2":"9"}},{"t":"case","label":"Semtek Int’l Inc. v. Lockheed Martin Corp.","cite":"531 U.S. 497","y":2001,"id":"2000/99-1551","sc":1,"op":2,"ar":1,"sum":"The Court held that \"[b]ecause the claim-preclusive effect of a federal court's dismissal 'upon the merits' of a diversity action on state statute-of-limitations grounds is governed by a federal rule, which in turn (in diversity cases) incorporates the claim-preclusion law that would be applied by state courts in the State in which the federal court sits, the Maryland Court of Special Appeals erred in holding that the California federal court's dismissal 'upon the merits' necessarily precluded the Maryland state-court action.\" Thus, the District Court's dismissal on the merits of claims as untimely under California law did not preclude Semtek from asserting its claims in a different state court forum.","sumSrc":"Oyez","by":{"0":"15, 35","1":"16, 19, 33, 46","2":"5"}},{"t":"case","label":"Serra v. Pichardo","cite":"786 F.2d 237","y":1986,"url":"https://www.courtlistener.com/c/F.2d/786/237/","by":{"0":"40","2":"13"}},{"t":"case","label":"Simmons v. Himmelreich","cite":"136 S. Ct. 1843","y":2016,"id":"2015/15-109","sc":1,"op":3,"ar":9,"sum":"The Court determined that the judgment bar of the Federal Tort Claims Act (FTCA) does not apply to claims dismissed for falling under the exceptions to the FTCA.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Tait v. Western Md. Ry. Co.","cite":"289 U.S. 620","y":1933,"id":"scdb/1932-093","sc":1,"sum":"that the judgment worked an estoppel against the United States and the Collector in later litigation with the corporation, as to its right to make like deductions for subsequent years under the same statutory provisions and Treasury regulations. Pp. 623, 625.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"United States v. California & Or. Land Co.","cite":"192 U.S. 355","y":1904,"id":"scdb/1903-212","sc":1,"sum":"A decree rendered upon a bill in equity brought under the Act of March 2, 1889, 25 Stat. 850, to have patents for land declared void as forfeited and to establish the title of the United States to the land, is a bar to a subsequent bill brought against the same defendants to recover the same land on the ground that it was excepted from the original grant as an Indian reservation.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"United States v. Gilman","cite":"347 U.S. 507","y":1954,"id":"scdb/1953-072","sc":1,"sum":"The United States is not entitled to recover indemnity from one of its employees for whose negligence it has been held liable under the Federal Tort Claims Act. Pp, 507-513. 206 F. 2d 846, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 27, 40","1":"20, 42","2":"12, 17, 19"}},{"t":"case","label":"Unus v. Kane","cite":"565 F.3d 103","y":2009,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/565/103/","op":1,"sum":"Holding that summary judgment on the plaintiffs’ FTCA claims triggered judgment bar with respect to Bivens claims.","sumSrc":"opinion","by":{"0":"19, 20, 36, 43","1":"34"}},{"t":"case","label":"White v. United States","cite":"959 F.3d 328","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/959/328/","by":{"0":"19, 36, 43","1":"34"}},{"t":"case","label":"Will v. Hallock","cite":"546 U.S. 345","y":2006,"id":"2005/04-1332","sc":1,"op":2,"ar":3,"sum":"The Court ruled that the Circuit Court had no jurisdiction to hear an appeal under the collateral order doctrine. Writing for the Court, Justice David Souter stressed the narrow scope of the doctrine. The Court reiterated that only orders that cannot be \"effectively\" reviewed after a final judgment can be appealed before the close of the trial.","sumSrc":"Oyez","by":{"0":"5, 22, 27, 46","1":"passim","2":"10, 15, 17, 18, 21"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"8"}},{"t":"law","label":"Pub. L. No. 100-694","url":"https://www.govinfo.gov/link/statute/102/4563","by":{"0":"20"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)","(b)(1)"],"stext":{"head":"§1346. United States as defendant","paras":[[0,"(a) The district courts shall have original jurisdiction, concurrent with the United States Court of Federal Claims, of:"],[1,"(1) Any civil action against the United States for the recovery of any internal-revenue tax alleged to have been erroneously or illegally assessed or collected, or any penalty claimed to have been collected without authority or any sum alleged to have been excessive or in any manner wrongfully collected under the internal-revenue laws;"],[1,"(2) Any other civil action or claim against the United States, not exceeding $10,000 in amount, founded either upon the Constitution, or any Act of Congress, or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort, except that the district courts shall not have jurisdiction of any civil action or claim against the United States founded upon any express or implied contract with the United States or for liquidated or unliquidated damages in cases not sounding in tort which are subject to sections 7104(b)(1) and 7107(a)(1) of title 41. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(b)(1) Subject to the provisions of chapter 171 of this title, the district courts, together with the United States District Court for the District of the Canal Zone and the District Court of the Virgin Islands, shall have exclusive jurisdiction of civil actions on claims against the United States, for money damages, accruing on and after January 1, 1945, for injury or loss of property, or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred."],[0,"(2) No person convicted of a felony who is incarcerated while awaiting sentencing or while serving a sentence may bring a civil action against the United States or an agency, officer, or employee of the Government, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(c) The jurisdiction conferred by this section includes jurisdiction of any set-off, counterclaim, or other claim or demand whatever on the part of the United States against any plaintiff commencing an action under this section."],[0,"(d) The district courts shall not have jurisdiction under this section of any civil action or claim for a pension."],[0,"(e) The district courts shall have original jurisdiction of any civil action against the United States provided in section 6226, 6228(a), 7426, or 7428 (in the case of the United States district court for the District of Columbia) or section 7429 of the Internal Revenue Code of 1986."],[0,"(f) The district courts shall have exclusive original jurisdiction of civil actions under section 2409a to quiet title to an estate or interest in real property in which an interest is claimed by the United States."],[0,"(g) Subject to the provisions of chapter 179, the district courts of the United States shall have exclusive jurisdiction over any civil action commenced under section 453(2) of title 3, by a covered employee under chapter 5 of such title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1346?type=usc&year=mostrecent&link-type=html"},"ar":3,"head":"§1346. United States as defendant","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 3, 3, 4, 14, 23, 25, 26, 3, 4, 14, 23, 25, 26","1":"passim","2":"8, 5, passim"}},{"t":"usc","label":"28 U.S.C. § 2402","url":"https://www.law.cornell.edu/uscode/text/28/2402","by":{"0":"3, 4, 14, 23, 25, 26"}},{"t":"usc","label":"28 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/28/2671","by":{"0":"passim"}},{"t":"usc","label":"28 U.S.C. § 2672","url":"https://www.law.cornell.edu/uscode/text/28/2672","stext":{"head":"§2672. Administrative adjustment of claims","paras":[[0,"The head of each Federal agency or his designee, in accordance with regulations prescribed by the Attorney General, may consider, ascertain, adjust, determine, compromise, and settle any claim for money damages against the United States for injury or loss of property or personal injury or death caused by the negligent or wrongful act or omission of any employee of the agency while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred: Provided, That any award, compromise, or settlement in excess of $25,000 shall be effected only with the prior written approval of the Attorney General or his designee. Notwithstanding the proviso contained in the preceding sentence, any award, compromise, or settlement may be effected without the prior written approval of the Attorney General or his or her designee, to the extent that the Attorney General delegates to the head of the agency the authority to make such award, compromise, or settlement. Such delegations may not exceed the authority delegated by the Attorney General to the United States attorneys to settle claims for money damages against the United States. Each Federal agency may use arbitration, or other alternative means of dispute resolution under the provisions of subchapter IV of chapter 5 of title 5, to settle any tort claim against the United States, to the extent of the agency's authority to award, compromise, or settle such claim without the prior written approval of the Attorney General or his or her designee."],[0,"Subject to the provisions of this title relating to civil actions on tort claims against the United States, any such award, compromise, settlement, or determination shall be final and conclusive on all officers of the Government, except when procured by means of fraud."],[0,"Any award, compromise, or settlement in an amount of $2,500 or less made pursuant to this section shall be paid by the head of the Federal agency concerned out of appropriations available to that agency. Payment of any award, compromise, or settlement in an amount in excess of $2,500 made pursuant to this section or made by the Attorney General in any amount pursuant to section 2677 of this title shall be paid in a manner similar to judgments and compromises in like causes and appropriations or funds available for the payment of such judgments and compromises are hereby made available for the payment of awards, compromises, or settlements under this chapter."],[0,"The acceptance by the claimant of any such award, compromise, or settlement shall be final and conclusive on the claimant, and shall constitute a complete release of any claim against the United States and against the employee of the government whose act or omission gave rise to the claim, by reason of the same subject matter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2672?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":2,"head":"§2672. Administrative adjustment of claims","tname":"Judiciary and Judicial Procedure","by":{"0":"passim","2":"18"}},{"t":"usc","label":"28 U.S.C. § 2675","url":"https://www.law.cornell.edu/uscode/text/28/2675","subs":["(a)"],"by":{"0":"passim"}},{"t":"usc","label":"28 U.S.C. § 2676","url":"https://www.law.cornell.edu/uscode/text/28/2676","stext":{"head":"§2676. Judgment as bar","paras":[[0,"The judgment in an action under section 1346(b) of this title shall constitute a complete bar to any action by the claimant, by reason of the same subject matter, against the employee of the government whose act or omission gave rise to the claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2676?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":7,"head":"§2676. Judgment as bar","tname":"Judiciary and Judicial Procedure","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(b)","(b)(1)","(b)(2)","(b)(2)(A)","(d)"],"stext":{"head":"§2679. Exclusiveness of remedy","paras":[[0,"(a) The authority of any federal agency to sue and be sued in its own name shall not be construed to authorize suits against such federal agency on claims which are cognizable under section 1346(b) of this title, and the remedies provided by this title in such cases shall be exclusive."],[0,"(b)(1) The remedy against the United States provided by sections 1346(b) and 2672 of this title for injury or loss of property, or personal injury or death arising or resulting from the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment is exclusive of any other civil action or proceeding for money damages by reason of the same subject matter against the employee whose act or omission gave rise to the claim or against the estate of such employee. Any other civil action or proceeding for money damages arising out of or relating to the same subject matter against the employee or the employee's estate is precluded without regard to when the act or omission occurred."],[0,"(2) Paragraph (1) does not extend or apply to a civil action against an employee of the Government—"],[1,"(A) which is brought for a violation of the Constitution of the United States, or"],[1,"(B) which is brought for a violation of a statute of the United States under which such action against an individual is otherwise authorized."],[0,"(c) The Attorney General shall defend any civil action or proceeding brought in any court against any employee of the Government or his estate for any such damage or injury. The employee against whom such civil action or proceeding is brought shall deliver within such time after date of service or knowledge of service as determined by the Attorney General, all process served upon him or an attested true copy thereof to his immediate superior or to whomever was designated by the head of his department to receive such papers and such person shall promptly furnish copies of the pleadings and process therein to the United States attorney for the district embracing the place wherein the proceeding is brought, to the Attorney General, and to the head of his employing Federal agency."],[0,"(d)(1) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a United States district court shall be deemed an action against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant."],[0,"(2) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a State court shall be removed without bond at any time before trial by the Attorney General to the district court of the United States for the district and division embracing the place in which the action or proceeding is pending. Such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. This certification of the Attorney General shall conclusively establish scope of office or employment for purposes of removal."],[0,"(3) In the event that the Attorney General has refused to certify scope of office or employment under this section, the employee may at any time before trial petition the court to find and certify that the employee was acting within the scope of his office or employment. Upon such certification by the court, such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. A copy of the petition shall be served upon the United States in accordance with the provisions of Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. In the event the petition is filed in a civil action or proceeding pending in a State court, the action or proceeding may be removed without bond by the Attorney General to the district court of the United States for the district and division embracing the place in which it is pending. If, in considering the petition, the district court determines that the employee was not acting within the scope of his office or employment, the action or proceeding shall be remanded to the State court."],[0,"(4) Upon certification, any action or proceeding subject to paragraph (1), (2), or (3) shall proceed in the same manner as any action against the United States filed pursuant to section 1346(b) of this title and shall be subject to the limitations and exceptions applicable to those actions."],[0,"(5) Whenever an action or proceeding in which the United States is substituted as the party defendant under this subsection is dismissed for failure first to present a claim pursuant to section 2675(a) of this title, such a claim shall be deemed to be timely presented under section 2401(b) of this title if—"],[1,"(A) the claim would have been timely had it been filed on the date the underlying civil action was commenced, and"],[1,"(B) the claim is presented to the appropriate Federal agency within 60 days after dismissal of the civil action."],[0,"(e) The Attorney General may compromise or settle any claim asserted in such civil action or proceeding in the manner provided in section 2677, and with the same effect."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2679?type=usc&year=mostrecent&link-type=html"},"head":"§2679. Exclusiveness of remedy","tname":"Judiciary and Judicial Procedure","by":{"0":"33, 33, 33, 33, 33","2":"13, 20, 20"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(a)","(h)"],"stext":{"head":"§2680. Exceptions","paras":[[0,"The provisions of this chapter and section 1346(b) of this title shall not apply to—"],[0,"(a) Any claim based upon an act or omission of an employee of the Government, exercising due care, in the execution of a statute or regulation, whether or not such statute or regulation be valid, or based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the part of a federal agency or an employee of the Government, whether or not the discretion involved be abused."],[0,"(b) Any claim arising out of the loss, miscarriage, or negligent transmission of letters or postal matter."],[0,"(c) Any claim arising in respect of the assessment or collection of any tax or customs duty, or the detention of any goods, merchandise, or other property by any officer of customs or excise or any other law enforcement officer, except that the provisions of this chapter and section 1346(b) of this title apply to any claim based on injury or loss of goods, merchandise, or other property, while in the possession of any officer of customs or excise or any other law enforcement officer, if—"],[1,"(1) the property was seized for the purpose of forfeiture under any provision of Federal law providing for the forfeiture of property other than as a sentence imposed upon conviction of a criminal offense;"],[1,"(2) the interest of the claimant was not forfeited;"],[1,"(3) the interest of the claimant was not remitted or mitigated (if the property was subject to forfeiture); and"],[1,"(4) the claimant was not convicted of a crime for which the interest of the claimant in the property was subject to forfeiture under a Federal criminal forfeiture law..1"],[0,"(d) Any claim for which a remedy is provided by chapter 309 or 311 of title 46 relating to claims or suits in admiralty against the United States."],[0,"(e) Any claim arising out of an act or omission of any employee of the Government in administering the provisions of sections 1–31 of Title 50, Appendix.2"],[0,"(f) Any claim for damages caused by the imposition or establishment of a quarantine by the United States."],[0,"[(g) Repealed. Sept. 26, 1950, ch. 1049, §13 (5), 64 Stat. 1043.]"],[0,"(h) Any claim arising out of assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights: Provided, That, with regard to acts or omissions of investigative or law enforcement officers of the United States Government, the provisions of this chapter and section 1346(b) of this title shall apply to any claim arising, on or after the date of the enactment of this proviso, out of assault, battery, false imprisonment, false arrest, abuse of process, or malicious prosecution. For the purpose of this subsection, \"investigative or law enforcement officer\" means any officer of the United States who is empowered by law to execute searches, to seize evidence, or to make arrests for violations of Federal law."],[0,"(i) Any claim for damages caused by the fiscal operations of the Treasury or by the regulation of the monetary system."],[0,"(j) Any claim arising out of the combatant activities of the military or naval forces, or the Coast Guard, during time of war."],[0,"(k) Any claim arising in a foreign country."],[0,"(l) Any claim arising from the activities of the Tennessee Valley Authority."],[0,"(m) Any claim arising from the activities of the Panama Canal Company."],[0,"(n) Any claim arising from the activities of a Federal land bank, a Federal intermediate credit bank, or a bank for cooperatives."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2680?type=usc&year=mostrecent&link-type=html"},"head":"§2680. Exceptions","tname":"Judiciary and Judicial Procedure","by":{"0":"33, 33, 33","1":"12, 23","2":"10, 19"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(a)"],"stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"head":"§1332. Diversity of citizenship; amount in controversy; costs","tname":"Judiciary and Judicial Procedure","by":{"0":"33","1":"40"}},{"t":"usc","label":"42 U.S.C. § 233","url":"https://www.law.cornell.edu/uscode/text/42/233","subs":["(a)"],"by":{"0":"39, 44"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"7"}},{"t":"case","label":"Allen v. McCurry","cite":"449 U.S. 90","y":1980,"id":"1980/79-935","sc":1,"sum":"The Court of Appeals erred in holding that respondent's inability to obtain federal habeas corpus relief upon his Fourth Amendment claim renders the doctrine of collateral estoppel inapplicable to his § 1983 suit. Nothing in the language or legislative history of § 1983 discloses any congressional intent to deny binding effect to a state-court judgment or decision when the state court, acting within its proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Amadeo v. Principal Mut. Life Ins. Co.","cite":"290 F.3d 1152","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/290/1152/","by":{"1":"26"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"op":2,"ar":2,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"1":"39, 40, 41, 43","2":"5"}},{"t":"case","label":"Baltimore S.S. Co. v. Phillips","cite":"274 U.S. 316","y":1927,"id":"scdb/1926-111","sc":1,"sum":"1. A judgment in an action for personal injuries, based on one ground of negligence, bars a second action, for the same injuries, based on another ground of negligence.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16, 27"}},{"t":"case","label":"Bank of Iron Gate v. Brady","cite":"184 U.S. 665","y":1902,"id":"scdb/1901-068","sc":1,"sum":"A tort by which the estate of the defendant was not increased, and the estate of the plaintiff damaged only as an indirect consequence of the alleged wrongful act of the defendant, does not, either at common law or by the statutes of Yirginia, survive the death of the wrongdoer.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Baxter v. Central W. Cas. Co.","cite":"58 P.2d 835","y":1936,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/58/835/","by":{"1":"17"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"ar":1,"sum":"1. Where the complaint seeks recovery squarely on the ground of violation of plaintiffs' rights under the Fourth and Fifth Amendments, a federal district court has jurisdiction of a suit against agents of the Federal Government to recover damages in excess of $3,000 alleged to have been suffered by the plaintiffs as a result of such violations-even though neither the Constitution nor the Congress has provided for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Bernhard v. Bank of Am. Nat’l Tr. & Sav. Ass’n","cite":"122 P.2d 892","y":1942,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/122/892/","by":{"1":"21"}},{"t":"case","label":"Bigelow v. Old Dominion Copper Mining & Smelting Co.","cite":"225 U.S. 111","y":1912,"id":"scdb/1911-059","sc":1,"sum":"One of two joint tort-feasors was sued in the'Circuit Court of the United States for New York, jurisdiction being based solely on diversity of citizenship, and the bill was dismissed; the other joint tort-feasor, who resided in Massachusetts, and was not, and could no+, be made a party defendant in the New York suit, having been sued in the state court of Massachusetts, set up the New York judgment, claiming that …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18, 20"}},{"t":"case","label":"Bissell v. Township of Spring Valley","cite":"124 U.S. 225","y":1888,"id":"scdb/1887-100","sc":1,"sum":",The entry of final judgment on demurrer concludes the parties to it, by way of estoppel, in a subsequent action between the same parties on a different claim, so far as the new controversy relates to the. matters litigated and determined in the prior action.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Blitz v. United States","cite":"153 U.S. 308","y":1894,"id":"scdb/1893-235","sc":1,"sum":"B. having been indicted under Rev. Stat. § 5511 for voting more than once at the same election for a Representative in.Congress, a special deputy of the marshal swore at the trial that he saw B. vote twicé at the poll. On cross-examination he was asked why he did not arrest B. when he saw that he had thus voted. The question, being objected to, was excluded. Held, that it was irrelevant and was properly excluded.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Bravo-Fernandez v. United States","cite":"137 S. Ct. 352","y":2016,"id":"2016/15-537","sc":1,"sum":"The Court decided that the Double Jeopardy Clause does not bar retrial when a jury returns an inconsistent verdict of conviction and acquittal and the convictions are later vacated for a completely separate legal error.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Chantangco v. Abaroa","cite":"218 U.S. 476","y":1910,"id":"scdb/1910-026","sc":1,"sum":"The general rule of the common law is that a judgment in a criminal proceeding cannot be read in evidence in a civil action to establish any fact there determined. The parties are not the same and different rules of evidence are applicable,.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"City of Elmhurst v. Kegerreis","cite":"64 N.E.2d 450","y":1945,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/64/450/","by":{"1":"16"}},{"t":"case","label":"Commissioner of Internal Revenue v. Sunnen","cite":"333 U.S. 591","y":1948,"id":"scdb/1947-064","sc":1,"sum":"The facts were sufficient to. support a finding by the Tax Court that the taxpayer retained sufficient interest in the royalty contracts and sufficient control overthe amount of income derived therefrom to justify taxing the income as his.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Corbett v. Craven","cite":"215 U.S. 125","y":1909,"id":"scdb/1909-014","sc":1,"sum":"The determination by a state court that a purchaser pendente lite from' the trustee of a bankrupt is bound by the decree against the trustee in the action of Which he has notice gives effect to such decree under the principles of general law; and if, as in this case, it does not involve passing on the nature and character of the rights of the patties arising from the transaction of purchase and sale, no Federal …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Costello v. United States","cite":"365 U.S. 265","y":1961,"id":"1960/59","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Cromwell v. County of Sac","cite":"94 U.S. 351","y":1876,"id":"scdb/1876-174","sc":1,"sum":"The action was on certain bonds and coupons thereto attached, issued by the county of Sac, in the State of Iowa. The facts are sufficiently stated in the opinion ofthe court. The defendant obtained judgment, and the plaintiff brought the case here.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"passim","2":"16"}},{"t":"case","label":"Darling Stores Corp. v. Beatus","cite":"33 S.E.2d 701","y":1945,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/33/701/","by":{"1":"17"}},{"t":"case","label":"Dolan v. United States Postal Serv.","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"op":1,"sum":"The Court ruled that the \"negligent transmission\" exception was inapplicable to Dolan's case, and therefore sovereign immunity had been waived and her case could proceed. The Court accepted Dolan's argument that the exception was only meant to encompass cases of late, missing, or incorrectly delivered mail.","sumSrc":"Oyez","by":{"1":"25, 37"}},{"t":"case","label":"Elder v. New York & Pa. Motor Express","cite":"31 N.E.2d 188","y":1940,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/31/188/","by":{"1":"21"}},{"t":"case","label":"Fayerweather v. Ritch","cite":"195 U.S. 276","y":1904,"id":"scdb/1904-027","sc":1,"sum":"Where the appellant’s contention is that the Circuit Court, by giving unwarranted effect to a judgment of a state court and accepting that judgment, which contained no finding of one of the fundamental facts as a conclusive determination of that fact, deprived him of his property without due process of law, and that contention is made ih good faith, and under the circumstances, upon reasonable grounds, the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Fazaga v. FBI","cite":"965 F.3d 1015","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/965/1015/","by":{"1":"34","2":"15"}},{"t":"case","label":"Feres v. United States","cite":"340 U.S. 135","y":1950,"id":"scdb/1950-013","sc":1,"by":{"1":"36, 45"}},{"t":"case","label":"Furneaux v. First Nat’l Bank","cite":"17 P. 854","y":1888,"court":"Kan.","url":"https://www.courtlistener.com/c/P./17/854/","by":{"1":"16"}},{"t":"case","label":"G. & C. Merriam Co. v. Saalfield","cite":"241 U.S. 22","y":1916,"id":"scdb/1915-220","sc":1,"op":1,"sum":"Whether* the District Court has acquired jurisdiction over the person of defendant may be reviewed by this court on direct appeal under § 238, Judicial Code.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Georgia v. Rachel","cite":"384 U.S. 780","y":1966,"id":"1965/147","sc":1,"sum":"\" Respondents were arrested on various dates in 1963 when they sought service at Atlanta restaurants. They were charged under the Georgia criminal trespass statute and petitioned for removal of the prosecutions to the Federal District Court under 28 U. S. C: § 1443. The petition alleged that the arrests and prosecutions were racially motivated. Under subsection (1) of § 1443, which pertinently provides for removal …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Giedrewicz v. Donovan","cite":"179 N.E. 246","y":1932,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./179/246/","by":{"1":"21"}},{"t":"case","label":"Goddard v. Security Title Ins. & Guar. Co.","cite":"92 P.2d 804","y":1939,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/92/804/","by":{"1":"16, 19, 33"}},{"t":"case","label":"Hallock v. Bonner","cite":"281 F. Supp. 2d 425","y":2003,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/281/425/","sum":"Describing a hypothetical procedural history identical to this case to illustrate, reductio ad absurdum, the “destructive” effect of applying the judgment bar absent FTCA jurisdiction.","sumSrc":"brief:1","by":{"1":"48"}},{"t":"case","label":"Hartford Life Ins. Co. v. Blincoe","cite":"255 U.S. 129","y":1921,"id":"scdb/1920-170","sc":1,"sum":"1. In determining how far a decision of this court reversing a judg- ment of a state court binds that court on a second trial, the principle of res jwjieata, that all that might have been decided is presumed to have been decided, is inapplicable; and only those masters which were, not merely presented and argued hero, but actually considered and decided by this court, are foreclosed.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"1":"41","2":"6"}},{"t":"case","label":"Hoosier Bancorp of Ind., Inc. v. Rasmussen","cite":"90 F.3d 180","y":1996,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/90/180/","by":{"1":"30"}},{"t":"case","label":"Howe v. Farmers’ & Merchs.’ Bank","cite":"264 P. 210","y":1928,"court":"Okla.","url":"https://www.courtlistener.com/c/P./264/210/","by":{"1":"17"}},{"t":"case","label":"Insurance Corp. of Ir., Ltd. v. Compagnie des Bauxites de Guinee","cite":"456 U.S. 694","y":1982,"id":"1981/81-440","sc":1,"sum":"Federal Rule of Civil Procedure 37(b)(2)(A) provides that a district court, as a sanction for failure to comply with discovery orders, may enter \"[ain order that the matters regarding which the [discovery] order was made or any other designated facts shall be taken to be established for the purposes of the action in accordance with the claim of the party obtaining the order.\" Asserting diversity jurisdiction, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35, 43, 44"}},{"t":"case","label":"Johnson Steel St. Rail Co. v. William Wharton, Jr. & Co.","cite":"152 U.S. 252","y":1894,"id":"scdb/1893-166","sc":1,"sum":"A judgment recovered in a Circuit Court of the United States in favor of the plaintiff by the owner of a patent right in an action against a licensee to recover royalties on sales of the patented article, where the sole defence set up was that the articles manufactured and sold by the defendant were not covered by the patent, in which the amount recovered was not sufficient to permit a review in this court, is a bar …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Keokuk & W. R.R. Co. v. Missouri","cite":"152 U.S. 301","y":1894,"id":"scdb/1893-169","sc":1,"sum":"A railroad corporation, chartered in Missouri in 1857,- with a provision that its property should be exempt from taxation for a period of twenty years after its completion, which toot place in 1872, was consolidated with an Iowa corporation in 1870., under a general law of Missouri, and in 1886 the consolidated road was sold'under a decree of foreclosure of a mortgage to purchasers who conveyed it to an Iowa …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Lauderdale v. Industrial Comm’n","cite":"139 P.2d 449","y":1943,"court":"Ariz.","url":"https://www.courtlistener.com/c/P.2d/139/449/","by":{"1":"16"}},{"t":"case","label":"Little v. Barlow","cite":"20 So. 240","y":1896,"court":"Fla.","url":"https://www.courtlistener.com/c/So./20/240/","by":{"1":"17"}},{"t":"case","label":"Mansfield, C. & L.M. Ry. Co. v. Swan","cite":"111 U.S. 379","y":1884,"id":"scdb/1883-231","sc":1,"sum":"Removal of Causes — Jurisdiction—Costs.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Milne v. Deen","cite":"121 U.S. 525","y":1887,"id":"scdb/1886-235","sc":1,"sum":"A judgment rendered on the merits in air action in a court of record is a bar to a second suit between the'same parties on the same cause of action; and when the second suit involves other matter as well as the matters in. issue in the former action, the former judgment, operates as an estoppel as to,those things which were in issue there, and upon the determination of which the first verdict was rendered.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Molzof v. United States","cite":"502 U.S. 301","y":1992,"id":"1991/90-838","sc":1,"sum":"The District Court awarded the guardian ad litem of petitioner Molzof's since-deceased husband damages under the Federal Tort Claims Act (FTCA or Act) for supplemental medical care for injuries suffered by Mr. Molzof as a result of the negligence of federal employees, but refused to award damages for future medical expenses and for loss of enjoyment of life. The Court of Appeals affirmed, ruling that damages of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 15, 25"}},{"t":"case","label":"Montgomery v. Samory","cite":"99 U.S. 482","y":1878,"id":"scdb/1878-147","sc":1,"by":{"1":"16"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Myers v. International Tr. Co.","cite":"263 U.S. 64","y":1923,"id":"scdb/1923-011","sc":1,"sum":"A judgment in bankruptcy confirming a composition over a creditor's objection based on the allegation that the bankrupts had obtained credit by a false statement of their financial condition, is not res judicata as to the creditor's cause of action against the bankrupts for the same alleged deceit; but estops the creditor as to the issue of falsity where this was not only raised, but actually decided against him, in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Myers’ Adm’x v. Brown","cite":"61 S.W.2d 1052","y":1933,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/61/1052/","by":{"1":"21"}},{"t":"case","label":"New Hampshire v. Maine","cite":"532 U.S. 742","y":2001,"id":"2000/130_orig","sc":1,"sum":"The Court held that \"judicial estoppel bars New Hampshire from asserting that the Piscataqua River boundary runs along the Maine shore.\" Under the judicial estoppel doctrine, \"[w]here a party assumes a certain position in a legal proceeding, and succeeds in maintaining that position, he may not thereafter, simply because his interests have changed, assume a contrary position, especially if it be to the prejudice of the party who has acquiesced in the position formerly taken by him,\" wrote Justice Ginsburg. \"New Hampshire's claim that the Piscataqua River boundary runs along the Maine shore is clearly inconsistent with its interpretation of the words 'Middle of the River' during the 1970's litigation,\" concluded Ginsburg.","sumSrc":"Oyez","by":{"1":"49","2":"12"}},{"t":"case","label":"North St. Louis Gymnastic Soc’y v. Hagerman","cite":"135 S.W. 42","y":1911,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W./135/42/","by":{"1":"16"}},{"t":"case","label":"Northern Pac. Ry. Co. v. Slaght","cite":"205 U.S. 122","y":1907,"id":"scdb/1906-142","sc":1,"sum":"A judgment on demurrer is as conclusive as one rendered upon proof.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Owen Equip. & Erection Co. v. Kroger","cite":"437 U.S. 365","y":1978,"id":"1977/77-677","sc":1,"sum":"The District Court had no power to entertain respondent's lawsuit against petitioner as a third-party defendant since diversity jurisdiction was lacking. Gibbs, supra, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Parklane Hosiery Co. v. Shore","cite":"439 U.S. 322","y":1979,"id":"1978/77-1305","sc":1,"sum":"Respondent brought this stockholder's class action in the District Court for damages and other relief against petitioners, a corporation, its officers, directors, and stockholders, who allegedly had issued a materially false and misleading proxy statement in violation of the federal securities laws and Securities and Exchange Commission (SEC) regulations. Before the action came to trial the SEC sued the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Postal Tel. Cable Co. v. City of Newport","cite":"247 U.S. 464","y":1918,"id":"scdb/1917-129","sc":1,"sum":"This court, will review and correct the error of a state supreme court, in assuming a state of facts without any support in the record as a basis for denying asserted federal rights.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18, 19"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Roberts v. Northern Pac. R.R. Co.","cite":"158 U.S. 1","y":1895,"id":"scdb/1894-181","sc":1,"sum":"Applying to this case the rules in regard to estoppel laid down in Cromwell v. Sac County, 94 U. S. 352, it is Held, that the question on point actually litigated in the state court in Ellis v. Northern Pacific Railroad, 77 Wisconsin, 114, was not the same with those before the Federal court in this case, and hence, as the causes of action in the two courts were not the. same, the judgment in the state court, while …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Sewell v. Watson","cite":"31 La. Ann. 589","y":1879,"url":"https://www.courtlistener.com/c/La.%20Ann./31/589/","by":{"1":"16"}},{"t":"case","label":"Spokane & Inland Empire R.R. Co. v. Whitley","cite":"237 U.S. 487","y":1915,"id":"scdb/1914-108","sc":1,"sum":"Decedent, who met his death in Idaho from the wrongful act of defendant railroad company left a wife and mother who under the laws of Idaho were his sole and equal heirs. The wife qualified as administratrix in Tennessee, and, having obtained power from the probate court of that State, to settle with defendant, sued as administratrix in Washington and recovered, without contest, a judgment which was paid. The mother …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"State v. School Dist. No. 1","cite":"50 P.2d 252","y":1935,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/50/252/","by":{"1":"17"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":3,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"46, 47"}},{"t":"case","label":"Stringer v. Conway Cty. Bridge Dist.","cite":"65 S.W.2d 1071","y":1933,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.2d/65/1071/","by":{"1":"16"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Treinies v. Sunshine Mining Co.","cite":"308 U.S. 66","y":1939,"id":"scdb/1939-024","sc":1,"by":{"1":"17"}},{"t":"case","label":"United Shoe Mach. Corp. v. United States","cite":"258 U.S. 451","y":1922,"id":"scdb/1921-104","sc":1,"sum":"1. A presumption of correctness attends the findings of fact made by the trial judge in an equity case after reading the evidence.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"United States v. Aetna Cas. & Sur. Co.","cite":"338 U.S. 366","y":1949,"id":"scdb/1949-019","sc":1,"sum":"Notwithstanding R. S. § 3477, restricting assignments of claims against the United States, an insurance company may bring an action under the Federal Tort Claims Act in its own name against the United States upon a claim to which it has become subrogated by payment to an insured who would have been able to bring such action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"1":"39, 40, 43"}},{"t":"case","label":"United States v. Tohono O’Odham Nation","cite":"563 U.S. 307","y":2011,"id":"2010/09-846","sc":1,"sum":"The Court held that the Court of Federal Claims lacked jurisdiction to hear a suit against the federal government about a claim already being litigated against the government in another court, even when the lawsuits seek different relief based on the same set of facts.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"United States v. United States Fid. & Guar. Co.","cite":"309 U.S. 506","y":1940,"id":"scdb/1939-047","sc":1,"sum":"In a reorganization proceeding in the District Court for the Western District of Missouri under § 77B of the Bankruptcy Act, the United States filed a claim in behalf of the Choctaw and Chickasaw Nations. The court allowed it but allowed the debtor's cross-claim for a larger amount and decreed the balance in favor of the debtor against the Nations to be \"collected in the manner provided by law.\" The validity of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 43"}},{"t":"case","label":"Vermont Agency of Nat. Res. v. United States","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Zastrow v. Milwaukee Elec. Ry. & Light Co.","cite":"198 N.W. 275","y":1924,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W./198/275/","by":{"1":"16"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"1":"40"}},{"t":"law","label":"Judicial Code and Judiciary, Pub. L. No. 80-773","by":{"1":"17"}},{"t":"rule","label":"Fed. R. Civ. P. 41","url":"https://www.law.cornell.edu/rules/frcp/rule_41","subs":["(b)"],"by":{"1":"45"}},{"t":"case","label":"Amell v. United States","cite":"384 U.S. 158","y":1966,"id":"1965/282","sc":1,"sum":"Petitioners, federal employees working aboard government vessels, filed actions for wages in the Court of Claims, predicating jurisdiction on the Tucker Act, which permits suits in that court on contractual claims against the Government and has a six-year statute of limitations. The Court of Claims granted respondent's motion to transfer the actions to various federal district courts on the ground that the claims …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Arevalo v. Woods","cite":"811 F.2d 487","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/811/487/","by":{"2":"15"}},{"t":"case","label":"California Pub. Emps. Retirement Sys. v. Anz Secs., Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Citizens’ Bank v. Parker","cite":"192 U.S. 73","y":1904,"id":"scdb/1903-067","sc":1,"sum":"When a contract is asserted and tbe Constitution of the United States invoked to protect it, all of the elements which are claimed to constitute it are open to examination and review by this court; and also all that which is claimed to have taken it away, and the writ of error will not be dismissed.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Gilman v. United States","cite":"206 F.2d 846","y":1953,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/206/846/","by":{"2":"19"}},{"t":"case","label":"MCI Telecomms. Corp. v. AT&T","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"17"}},{"t":"case","label":"United States v. Lushbough","cite":"200 F.2d 717","y":1952,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/200/717/","sum":"Holding that the judgment bar “explicit[ly]” precludes entry of “judgment against [the federal employee] in favor of [the plaintiff ] in the same action” after the district court has issued judgment for the plaintiff on FTCA claims.","sumSrc":"brief:2","by":{"2":"15, 19"}},{"t":"case","label":"United States v. Smith","cite":"499 U.S. 160","y":1991,"id":"1990/89-1646","sc":1,"sum":"The Act immunizes Government employees from suit even when an FTCA exception precludes recovery against the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"United States v. Southern Pac. Co.","cite":"259 U.S. 214","y":1922,"id":"scdb/1921-156","sc":1,"sum":"1. A combination whereby one railroad system, through stock purchases, acquires control of the whole or a vital part of another, with the effect of materially reducing free and normal competition in interstate trade between the two, violates the Sherman AntiTrust Act.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","by":{"2":"18"}},{"t":"usc","label":"28 U.S.C. § 2414","url":"https://www.law.cornell.edu/uscode/text/28/2414","by":{"2":"18"}},{"t":"usc","label":"31 U.S.C. § 1304","url":"https://www.law.cornell.edu/uscode/text/31/1304","subs":["(a)(3)(A)"],"by":{"2":"18"}},{"t":"usc","label":"46 U.S.C. § 30904","url":"https://www.law.cornell.edu/uscode/text/46/30904","by":{"2":"21"}},{"t":"rule","label":"Fed. R. Civ. P. 3","url":"https://www.law.cornell.edu/rules/frcp/rule_3","by":{"2":"8"}}]};